cd /home/ubuntu/koha-test
echo '' | base64 -d > entrypoint.sh
docker cp entrypoint.sh koha-test:/setup/entrypoint.sh
docker exec koha-test sh -c "grep -n '__MEMCACHED' /etc/koha/sites/kohadent/koha-conf.xml; sed -i 's/__MEMCACHED_SERVERS__/127.0.0.1:11211/; s/__MEMCACHED_NAMESPACE__/koha_kohadent/' /etc/koha/sites/kohadent/koha-conf.xml"
docker restart koha-test >/dev/null; sleep 45
docker ps --filter name=koha-test --format '{{.Status}}'
docker logs --since 50s koha-test 2>&1 | tail -6
curl -s -o /dev/null -w "staff %{http_code}\n" -m 20 https://koha.azoclinic.duckdns.org/cgi-bin/koha/mainpage.pl
curl -s -o /dev/null -w "opac %{http_code}\n" -m 20 https://opac.azoclinic.duckdns.org/
curl -s -m 20 https://koha.azoclinic.duckdns.org/api/v1/ | head -c 200; echo
